<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$rows=db()->query('SELECT a.*,ad.name admin_name FROM audit_logs a LEFT JOIN admins ad ON ad.id=a.admin_id ORDER BY a.created_at DESC LIMIT 300')->fetchAll();admin_header('Audit Log','audit.php');?><div class="pagehead"><div><h1>Audit Log</h1><div class="muted">Administrative actions recorded by the system.</div></div></div><div class="card table-wrap"><table class="table"><tr><th>Date</th><th>Admin</th><th>Action</th><th>Entity</th><th>ID</th><th>Details</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['admin_name']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['entity'])?></td><td><?=e($r['entity_id'])?></td><td><?=e($r['details'])?></td></tr><?php endforeach;?></table></div><?php admin_footer();
